// Installation bzw. Rückruf lesen (SHOPIFY 1, Migration 82; Fix 22.10.): alle Abfrageparameter (Text, höchstens 30, je bis 8192 Zeichen) und der Host der Anfrage.
// Shopify schickt bei der verwalteten Installation auch lange Werte (z. B. id_token); sie müssen für die HMAC-Prüfung vollständig mit. Prüfen macht die Datenbank.
const j = $input.first().json || {};
const q = j.query || {};
const h = j.headers || {};
const s = v => String((Array.isArray(v) ? v[0] : v) ?? '');
const aus = {};
let n = 0;
for (const k of Object.keys(q)) {
  if (!/^[a-z0-9_]{1,40}$/.test(k)) continue;
  const w = s(q[k]);
  if (w.length > 8192 || /[\x00-\x1f\x7f]/.test(w)) continue;
  if (++n > 30) break;
  aus[k] = w;
}
const host = String(h['x-forwarded-host'] || h.host || '').split(',')[0].trim().toLowerCase();
return [{ json: { q: JSON.stringify(aus), host: /^[a-z0-9.-]{3,253}$/.test(host) ? host : '' } }];

// Antwortseite (SHOPIFY 1): schlichte Seite ohne Skripte, neutral (Produktname aus den Einstellungen). Bei Erfolg der Installation: Weiterleitung (302) zur Zustimmung in Shopify.
const r = ($input.first().json || {}).r || {};
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const seite = (titel, text) => '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(titel) +
  '</title><style>body{font-family:system-ui,-apple-system,Segoe UI,sans-serif;background:#f4f5f3;color:#1f2933;margin:0;display:flex;min-height:100vh;align-items:center;justify-content:center}' +
  'main{background:#fff;border:1px solid #dde1dc;border-radius:14px;padding:28px 32px;max-width:460px;margin:16px}h1{font-size:20px;margin:0 0 10px}p{margin:0;line-height:1.5}</style></head>' +
  '<body><main><h1>' + esc(titel) + '</h1><p>' + esc(text) + '</p></main></body></html>';
if (r.ok === true && /^https:\/\/[a-z0-9][a-z0-9-]{0,59}\.myshopify\.com\/admin\/oauth\/authorize\?[^\s<>"]+$/.test(String(r.url || '')))
  return [{ json: { weiter: true, status: 302, location: String(r.url), html: '' } }];
return [{ json: { weiter: false, status: 400, location: '', html: seite('Verbindung nicht möglich', r.text || 'Ungültiger Aufruf.') } }];

// Installation bzw. Rückruf lesen (SHOPIFY 1, Migration 82; Fix 22.10.): alle Abfrageparameter (Text, höchstens 30, je bis 8192 Zeichen) und der Host der Anfrage.
// Shopify schickt bei der verwalteten Installation auch lange Werte (z. B. id_token); sie müssen für die HMAC-Prüfung vollständig mit. Prüfen macht die Datenbank.
const j = $input.first().json || {};
const q = j.query || {};
const h = j.headers || {};
const s = v => String((Array.isArray(v) ? v[0] : v) ?? '');
const aus = {};
let n = 0;
for (const k of Object.keys(q)) {
  if (!/^[a-z0-9_]{1,40}$/.test(k)) continue;
  const w = s(q[k]);
  if (w.length > 8192 || /[\x00-\x1f\x7f]/.test(w)) continue;
  if (++n > 30) break;
  aus[k] = w;
}
const host = String(h['x-forwarded-host'] || h.host || '').split(',')[0].trim().toLowerCase();
return [{ json: { q: JSON.stringify(aus), host: /^[a-z0-9.-]{3,253}$/.test(host) ? host : '' } }];

// Token holen (SHOPIFY 1, Migration 82; Fix 22.10.): tauscht den Code gegen das Token (Authorization Code Grant, expiring=1). Das Formular mit dem Client-Schlüssel kommt nur
// aus der Datenbank (shopify_oauth_rueckruf, nach Prüfung von state, HMAC und Shop) und nur an die Shop-Adresse *.myshopify.com. Keine Ausführungsdaten.
// Fix: Die Antwort kann als Text, Buffer oder bereits gelesenes Objekt ankommen.
const r = ($input.first().json || {}).r || {};
if (r.ok !== true) return [{ json: { shop_id: '', antwort: '', text: String(r.text || 'Ungültiger Aufruf.') } }];
const url = String(r.url || '');
if (!/^https:\/\/[a-z0-9][a-z0-9-]{0,59}\.myshopify\.com\/admin\/oauth\/access_token$/.test(url)) return [{ json: { shop_id: '', antwort: '', text: 'Ungültiger Aufruf.' } }];
const f = r.form || {};
const body = Object.keys(f).map(k => encodeURIComponent(k) + '=' + encodeURIComponent(String(f[k] ?? ''))).join('&');
const istBuf = x => typeof Buffer !== 'undefined' && Buffer.isBuffer(x);
const lies = b => {
  if (b && typeof b === 'object' && !istBuf(b)) return b;
  try { return JSON.parse(istBuf(b) ? b.toString('utf8') : String(b || '')); } catch (e) { return null; }
};
try {
  const a = await this.helpers.httpRequest({ method: 'POST', url, body, headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' },
    json: false, timeout: 30000, returnFullResponse: true, ignoreHttpStatusErrors: true });
  const d = lies(a.body);
  if (a.statusCode !== 200 || !d || !d.access_token) return [{ json: { shop_id: '', antwort: '', text: 'Shopify hat die Verbindung abgelehnt (' + a.statusCode + (d ? '' : ', Antwort nicht lesbar') + '). Bitte die App in Shopify erneut öffnen.' } }];
  const keep = {};
  for (const k of ['access_token', 'scope', 'expires_in', 'refresh_token', 'refresh_token_expires_in']) if (d[k] !== undefined) keep[k] = d[k];
  return [{ json: { shop_id: String(r.shop_id), antwort: JSON.stringify(keep), text: '' } }];
} catch (e) {
  return [{ json: { shop_id: '', antwort: '', text: 'Shopify ist gerade nicht erreichbar. Bitte später die App in Shopify erneut öffnen.' } }];
}

// Rückruf antworten (SHOPIFY 1): Ergebnisseite ohne Skripte, neutral.
const t = $('Token holen').first().json || {};
const r = ($input.first().json || {}).r || {};
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const seite = (titel, text) => '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(titel) +
  '</title><style>body{font-family:system-ui,-apple-system,Segoe UI,sans-serif;background:#f4f5f3;color:#1f2933;margin:0;display:flex;min-height:100vh;align-items:center;justify-content:center}' +
  'main{background:#fff;border:1px solid #dde1dc;border-radius:14px;padding:28px 32px;max-width:460px;margin:16px}h1{font-size:20px;margin:0 0 10px}p{margin:0;line-height:1.5}</style></head>' +
  '<body><main><h1>' + esc(titel) + '</h1><p>' + esc(text) + '</p></main></body></html>';
if (t.text || !r || r.ok !== true) return [{ json: { status: 400, html: seite('Verbindung nicht möglich', t.text || 'Die Verbindung konnte nicht gespeichert werden.') } }];
return [{ json: { status: 200, html: seite('Verbindung hergestellt', 'Der Shop ist jetzt verbunden. Du kannst dieses Fenster schließen.') } }];
